#!/usr/bin/env node
/**
 * Ordering.co brand adapter for the dashboard.
 *
 * The dashboard is a legacy styled-components app, so it does not run the
 * shadcn/Tailwind stack. It consumes the released brand tokens through an
 * adapter instead. There is ONE source of `--od-*` values:
 * `src/brand/ordering.tokens.generated.js` (generated by
 * `node scripts/brand-system.mjs release-update` from
 * `src/brand/sources/<release>/ordering.tokens.json`). This script no longer
 * generates a module. `OrderingBrand/allowlist.js` only names the subset the
 * login surface scopes, and the `ALLOWLIST` below (DTCG paths) is the check
 * that those names and values still resolve from the canonical file. Inter
 * and the vendored `brand/ordering.tokens.json` are pinned in
 * `brand/ordering-brand.lock.json` by release and sha256.
 *
 *   node scripts/brand-tokens.mjs check       offline: vendored files match the lock, the single token module and the allowlist
 *   node scripts/brand-tokens.mjs freshness   remote: the canonical files still match the lock
 *   node scripts/brand-tokens.mjs sync        remote: download and verify against the lock (writes no module)
 *   node scripts/brand-tokens.mjs sync --accept   take a new release: rewrite the lock with the remote sha256
 *
 * A brand update is a reviewable change: run `sync --accept`, then regenerate
 * `src/brand` with `node scripts/brand-system.mjs release-update`, read the diff.
 */
import { createHash } from 'node:crypto'
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import { fileURLToPath, pathToFileURL } from 'node:url'
import { runInNewContext } from 'node:vm'

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..')
export const LOCK_PATH = resolve(ROOT, 'brand/ordering-brand.lock.json')
export const TOKENS_PATH = resolve(ROOT, 'brand/ordering.tokens.json')
const BRAND_DIR = 'src/@/components-dashboard/src/ui/src/styles/OrderingBrand'
/** The single source of `--od-*` values, generated by scripts/brand-system.mjs. */
export const TOKEN_MODULE_PATH = resolve(ROOT, 'src/brand/ordering.tokens.generated.js')
/** Names the subset of variables the login surface scopes. */
export const ALLOWLIST_MODULE_PATH = resolve(ROOT, BRAND_DIR, 'allowlist.js')
/** The retired second generated module; it must stay deleted. */
export const RETIRED_GENERATED_PATH = resolve(ROOT, BRAND_DIR, 'tokens.generated.js')

/** Tokens the dashboard uses. Anything else stays out until a surface needs it. */
export const ALLOWLIST = {
  root: [
    'font.family.sans',
    'font.weight.regular',
    'font.weight.medium',
    'font.weight.semibold',
    'font.size.1',
    'font.size.2',
    'font.size.3',
    'font.size.6',
    'font.lineHeight.heading',
    'font.lineHeight.body',
    'font.tracking.heading',
    'radius.control',
    'radius.component',
    'radius.panel',
    'stroke.default',
    'shadow.1',
    'shadow.2',
    'motion.duration.fast',
    'motion.duration.base',
    'space.2',
    'space.3',
    'space.4',
    'space.5',
    'space.6',
    'space.7'
  ],
  mode: [
    'semantic.background',
    'semantic.surface.default',
    'semantic.surface.subtle',
    'semantic.surface.strong',
    'semantic.text.default',
    'semantic.text.muted',
    'semantic.text.inverse',
    'semantic.border.default',
    'semantic.border.strong',
    'semantic.action.default',
    'semantic.action.foreground',
    'semantic.action.content',
    'semantic.action.hover',
    'semantic.action.soft',
    'semantic.action.focus',
    'semantic.state.danger.functional',
    'semantic.state.danger.soft'
  ]
}

export const sha256 = (buffer) => createHash('sha256').update(buffer).digest('hex')

const readJson = (path) => JSON.parse(readFileSync(path, 'utf8'))

const getPath = (tree, path) => path.split('.').reduce((node, key) => node?.[key], tree)

const resolveValue = (tree, value, seen = new Set()) => {
  const match = typeof value === 'string' && value.match(/^\{([^}]+)\}$/)
  if (!match) return value
  if (seen.has(match[1])) throw new Error(`Token reference loop at ${match[1]}`)
  seen.add(match[1])
  const target = getPath(tree, match[1])
  if (!target || target.$value === undefined) throw new Error(`Unresolved token reference ${match[1]}`)
  return resolveValue(tree, target.$value, seen)
}

const toCss = (value) => Array.isArray(value) ? `cubic-bezier(${value.join(', ')})` : String(value)

const readToken = (tree, path) => {
  const token = getPath(tree, path)
  const variable = token?.$extensions?.ordering?.cssVariable
  if (!token || token.$value === undefined || !variable) throw new Error(`Allowlisted token ${path} is missing or has no cssVariable`)
  return [variable, toCss(resolveValue(tree, token.$value))]
}

/**
 * Reads the named exports of a self-contained data module (no imports of its
 * own). It is evaluated as text on purpose: the repo's package.json has no
 * "type": "module", so import() of these .js files from Node only works
 * through syntax detection (and prints MODULE_TYPELESS_PACKAGE_JSON), and
 * Vitest, which also loads this script, cannot run a native import() here. It
 * runs in a fresh `vm` context with no access to this process. A module that
 * gains an import fails loudly with a SyntaxError.
 */
const readStandalone = (path) => {
  const names = [...readFileSync(path, 'utf8').matchAll(/^export const (\w+)/gm)].map(match => match[1])
  const body = readFileSync(path, 'utf8').replace(/^export default .*$/gm, '').replace(/^export const /gm, 'const ')
  return runInNewContext(`${body}\n;({ ${names.join(', ')} })`)
}

/** Name and value of every allowlisted token, resolved from the canonical file. */
const resolveAllowlist = (tokens) => {
  const root = ALLOWLIST.root.map(path => readToken(tokens, path))
  const mode = (name) => ALLOWLIST.mode.map(path => readToken(tokens, `theme.${name}.${path}`))
  return { root, light: mode('light'), dark: mode('dark') }
}

const fetchBuffer = async (url) => {
  const response = await fetch(url)
  if (!response.ok) throw new Error(`${url} answered ${response.status}`)
  return Buffer.from(await response.arrayBuffer())
}

/** Offline parity. Returns a list of problems; empty means in sync. */
export const checkOffline = async () => {
  const problems = []
  const lock = readJson(LOCK_PATH)
  if (!existsSync(TOKENS_PATH)) return [`${TOKENS_PATH} is missing; run pnpm brand:sync`]
  const tokensBuffer = readFileSync(TOKENS_PATH)
  if (sha256(tokensBuffer) !== lock.tokens.sha256) problems.push('brand/ordering.tokens.json does not match the lock sha256')
  for (const [name, asset] of Object.entries(lock.assets)) {
    const path = resolve(ROOT, asset.path)
    if (!existsSync(path)) problems.push(`${name}: ${asset.path} is missing`)
    else if (sha256(readFileSync(path)) !== asset.sha256) problems.push(`${name}: ${asset.path} does not match the lock sha256`)
  }

  if (!existsSync(TOKEN_MODULE_PATH)) return [...problems, `${TOKEN_MODULE_PATH} is missing`]
  if (!existsSync(ALLOWLIST_MODULE_PATH)) return [...problems, `${ALLOWLIST_MODULE_PATH} is missing`]
  const { variables, metadata } = readStandalone(TOKEN_MODULE_PATH)
  const { ORDERING_BRAND_ALLOWLIST } = readStandalone(ALLOWLIST_MODULE_PATH)

  // One origin: the token module was generated from the same bytes as the vendored tokens.
  const sourcePath = resolve(ROOT, metadata?.generatedFrom ?? '')
  if (!metadata?.generatedFrom || !existsSync(sourcePath)) problems.push('src/brand/ordering.tokens.generated.js has no readable metadata.generatedFrom')
  else if (sha256(readFileSync(sourcePath)) !== sha256(tokensBuffer)) {
    problems.push(`brand/ordering.tokens.json differs from ${metadata.generatedFrom}; regenerate src/brand with node scripts/brand-system.mjs release-update`)
  }

  // The retired second module must not come back.
  if (existsSync(RETIRED_GENERATED_PATH)) problems.push(`${RETIRED_GENERATED_PATH} must not exist; the only --od-* source is src/brand/ordering.tokens.generated.js`)

  const resolved = resolveAllowlist(JSON.parse(tokensBuffer.toString('utf8')))

  // Every allowlisted name resolves to the same value in the token module (mode, then root, then product).
  const pools = { root: [variables.root, variables.product], light: [variables.light, variables.root, variables.product], dark: [variables.dark, variables.root, variables.product] }
  for (const [scope, entries] of Object.entries(resolved)) {
    for (const [name, value] of entries) {
      const pool = pools[scope].find(candidate => candidate[name] !== undefined)
      if (!pool) problems.push(`${scope} ${name} is not in src/brand/ordering.tokens.generated.js`)
      else if (pool[name] !== value) problems.push(`${scope} ${name}: src/brand/ordering.tokens.generated.js has "${pool[name]}", the canonical tokens give "${value}"`)
    }
  }

  // The names OrderingBrand/allowlist.js lists are exactly the allowlisted tokens, in order.
  const names = (entries) => entries.map(([name]) => name)
  const sameList = (actual, expected) => Array.isArray(actual) && actual.length === expected.length && expected.every((name, index) => actual[index] === name)
  if (names(resolved.light).join() !== names(resolved.dark).join()) problems.push('light and dark allowlist paths resolve to different variable names')
  if (!sameList(ORDERING_BRAND_ALLOWLIST?.root, names(resolved.root))) problems.push('OrderingBrand/allowlist.js root does not match the ALLOWLIST in scripts/brand-tokens.mjs')
  if (!sameList(ORDERING_BRAND_ALLOWLIST?.mode, names(resolved.light))) problems.push('OrderingBrand/allowlist.js mode does not match the ALLOWLIST in scripts/brand-tokens.mjs')
  return problems
}

const freshness = async () => {
  const lock = readJson(LOCK_PATH)
  const stale = []
  const remoteTokens = sha256(await fetchBuffer(lock.tokens.url))
  if (remoteTokens !== lock.tokens.sha256) stale.push(`tokens: remote ${remoteTokens} ≠ lock ${lock.tokens.sha256}`)
  for (const [name, asset] of Object.entries(lock.assets)) {
    const remote = sha256(await fetchBuffer(asset.url))
    if (remote !== asset.sha256) stale.push(`${name}: remote ${remote} ≠ lock ${asset.sha256}`)
  }
  return stale
}

const sync = async ({ accept }) => {
  const lock = readJson(LOCK_PATH)
  const tokensBuffer = await fetchBuffer(lock.tokens.url)
  const tokensSha = sha256(tokensBuffer)
  if (tokensSha !== lock.tokens.sha256) {
    if (!accept) throw new Error(`Remote tokens sha256 ${tokensSha} ≠ lock. Re-run with --accept to take the new release.`)
    lock.tokens.sha256 = tokensSha
    console.warn('The tokens sha256 changed. Regenerate src/brand with `node scripts/brand-system.mjs release-update`: brand:check fails until src/brand/sources matches brand/ordering.tokens.json.')
  }
  const tokens = JSON.parse(tokensBuffer.toString('utf8'))
  lock.tokens.version = tokens.version
  for (const [name, asset] of Object.entries(lock.assets)) {
    const buffer = await fetchBuffer(asset.url)
    const assetSha = sha256(buffer)
    if (assetSha !== asset.sha256) {
      if (!accept) throw new Error(`${name}: remote sha256 ${assetSha} ≠ lock. Re-run with --accept.`)
      asset.sha256 = assetSha
    }
    asset.bytes = buffer.length
    const path = resolve(ROOT, asset.path)
    mkdirSync(dirname(path), { recursive: true })
    writeFileSync(path, buffer)
  }
  mkdirSync(dirname(TOKENS_PATH), { recursive: true })
  writeFileSync(TOKENS_PATH, tokensBuffer)
  writeFileSync(LOCK_PATH, `${JSON.stringify(lock, null, 2)}\n`)
}

const main = async () => {
  const [command, ...flags] = process.argv.slice(2)
  if (command === 'check') {
    const problems = await checkOffline()
    if (problems.length) {
      console.error(problems.join('\n'))
      process.exit(1)
    }
    console.log('Ordering.co brand files match the lock.')
  } else if (command === 'freshness') {
    const stale = await freshness()
    if (stale.length) {
      console.error(`A newer brand release is published:\n${stale.join('\n')}\nRun pnpm brand:sync --accept and review the diff.`)
      process.exit(1)
    }
    console.log('The lock matches the published Ordering.co release.')
  } else if (command === 'sync') {
    await sync({ accept: flags.includes('--accept') })
    console.log('Ordering.co brand files synced (no module is generated here). Review the diff before committing.')
  } else {
    console.error('Usage: node scripts/brand-tokens.mjs <check|freshness|sync [--accept]>')
    process.exit(2)
  }
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  main().catch(error => {
    console.error(error.message)
    process.exit(1)
  })
}
